using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NewGameServiceTests
{
    static WorldSession Start(string site="site:kofu",bool retainer=false)=>NewGameWorldTests.Session([NewGameWorldTests.Officer(site:site,role:retainer?StartTemplate.Retainer:StartTemplate.Ronin,lord:retainer?"person:shingen":null)]);
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static void Send(WorldSession s,ServiceInput i)=>Assert.Equal(ResultCode.Accepted,s.DecideService(i,s.PlayerControl,s.Revision).Code);
    static EntityId Apply(WorldSession s,string principal="person:shingen",string id="request:apply"){Send(s,new(new(id),CareerAction.Apply,Principal:new(principal)));At(s,s.Seconds+2);Open(s);return new(id);}
    static EntityId Join(WorldSession s,string principal="person:shingen",string suffix=""){var id=Apply(s,principal,"request:apply"+suffix);Send(s,new(new("request:accept"+suffix),CareerAction.Accept,id));At(s,s.Seconds+2);Open(s);return id;}
    [Theory][InlineData("site:castle","person:nobunaga","org:oda")][InlineData("site:kofu","person:shingen","org:takeda")][InlineData("site:odawara","person:ujiyasu","org:hojo")]
    public void SamePersonJoinsLocalHouseWithoutTroops(string site,string principal,string house){var s=Start(site);var look=NewGameWorld.Look(s.DiagnosticSnapshot().NewGame!,s.PlayerControl.Value);Join(s,principal);var w=s.DiagnosticSnapshot();Assert.Equal(new EntityId(house),NewGameService.View(w).House);Assert.Equal(new EntityId(principal),NewGameService.View(w).Principal);Assert.Equal("created:test",s.PlayerControl.Value);Assert.Equal(ContractJson.Write(look),ContractJson.Write(NewGameWorld.Look(w.NewGame!,s.PlayerControl.Value)));Assert.Empty(w.Units);Assert.Empty(w.ResourceLots);Assert.DoesNotContain(w.LandRights,r=>r.Subject==s.PlayerControl);ContractValidation.Validate(w);}
    [Fact]public void SealedOfferCannotBeAccepted(){var s=Start();Send(s,new(new("request:apply"),CareerAction.Apply,Principal:new("person:shingen")));At(s,2);Assert.False(NewGameService.View(s.DiagnosticSnapshot()).Cases.Single().CanAccept);Assert.Equal(ResultCode.NotAvailable,s.DecideService(new(new("request:answer"),CareerAction.Accept,new("request:apply")),s.PlayerControl,s.Revision).Code);}
    [Fact]public void PhysicalAcceptancePrecedesKnownMembership(){var s=Start();var id=Apply(s);Send(s,new(new("request:answer"),CareerAction.Accept,id));At(s,3);Assert.True(NewGameService.BoundAt(s.DiagnosticSnapshot(),new("person:shingen"),3,s.Revision));Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).House);At(s,4);Open(s);Assert.NotNull(NewGameService.View(s.DiagnosticSnapshot()).House);}
    [Fact]public void RemoteAudienceIsRejectedWithoutMutation(){var s=Start();string h=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideService(new(new("request:remote"),CareerAction.Apply,Principal:new("person:nobunaga")),s.PlayerControl,s.Revision).Code);Assert.Equal(h,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void RequestReplayIsIdempotentAndConflictingPayloadRejected(){var s=Start();var input=new ServiceInput(new("request:one"),CareerAction.Apply,Principal:new("person:shingen"));Send(s,input);string h=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.DecideService(input,s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.DecideService(input with{Principal=new("person:nobunaga")},s.PlayerControl,s.Revision).Code);Assert.Equal(h,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void ServiceIdCannotBecomeMove(){var s=Start();Send(s,new(new("request:one"),CareerAction.Apply,Principal:new("person:shingen")));Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:one","castle"),s.Revision).Code);}
    [Fact]public void DeclineNeverCreatesMembership(){var s=Start();var id=Apply(s);Send(s,new(new("request:decline"),CareerAction.Decline,id));At(s,4);Open(s);Assert.DoesNotContain(s.DiagnosticSnapshot().Memberships,r=>r.Subject==s.PlayerControl);Assert.True(NewGameService.View(s.DiagnosticSnapshot()).CanApply);}
    [Fact]public void OfferExpiresBeforeLateAcceptance(){var s=Start();var id=Apply(s);At(s,122);Open(s);Assert.Equal(ResultCode.NotAvailable,s.DecideService(new(new("request:late"),CareerAction.Accept,id),s.PlayerControl,s.Revision).Code);Assert.DoesNotContain(s.DiagnosticSnapshot().Memberships,r=>r.Subject==s.PlayerControl);}
    [Fact]public void InitialRetainerCanLeaveWithoutFabricatedJoin(){var s=Start(retainer:true);var card=NewGameService.View(s.DiagnosticSnapshot()).Cases.Single();Send(s,new(new("request:leave"),CareerAction.RequestRelease,card.Case));At(s,2);Assert.DoesNotContain(s.DiagnosticSnapshot().Service!.Events,e=>e.Kind==CareerEventKind.Joined);Open(s);Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).House);Assert.All(s.DiagnosticSnapshot().Memberships.Where(r=>r.Subject==s.PlayerControl),r=>Assert.True(r.Until<s.Seconds+1));}
    [Fact]public void LocalWorkBecomesBindingOnlyAfterKnownService(){var s=Start();Join(s);var i=NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:work");Assert.Equal(TaskKind.BindingOrder,i.Kind);Assert.Equal(new EntityId("person:shingen"),i.Actor);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);At(s,s.Seconds+2);Open(s);Assert.DoesNotContain(s.DiagnosticSnapshot().Tasks,t=>t.Agreement==AgreementPhase.AwaitingAssent);}
    [Fact]public void LeaveWaitsForActualWorkReport(){var s=Start();var id=Join(s);Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:work"),s.Revision).Code);Send(s,new(new("request:leave"),CareerAction.RequestRelease,id));At(s,s.Seconds+2);Assert.Contains(s.DiagnosticSnapshot().Service!.Events,e=>e.Kind==CareerEventKind.ReleaseWaiting);Open(s);At(s,s.Seconds+10);Open(s);Assert.Contains(s.DiagnosticSnapshot().Service!.Events,e=>e.Kind==CareerEventKind.Released);Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).House);}
    [Fact]public void PersonalRetinueSurvivesJoinAndLeave(){var own=NewGameWorldTests.Officer(site:"site:kofu");var follower=NewGameWorldTests.Officer("created:follower",StartTemplate.Retainer,"site:kofu",own.Id);var s=NewGameWorldTests.Session([own,follower]);var original=s.DiagnosticSnapshot().ServiceBonds.Single(r=>r.Subject.Value==follower.Id);var id=Join(s);Send(s,new(new("request:leave"),CareerAction.RequestRelease,id));At(s,s.Seconds+2);Open(s);Assert.Equal(original,s.DiagnosticSnapshot().ServiceBonds.Single(r=>r.Subject.Value==follower.Id));}
    [Fact]public void SamePersonCanLeaveAndJoinAnotherHouse(){var s=Start();var id=Join(s);Send(s,new(new("request:leave"),CareerAction.RequestRelease,id));At(s,s.Seconds+2);Open(s);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:move","odawara"),s.Revision).Code);At(s,s.Seconds+2);var until=s.GetBranchView(s.PlayerControl).ArrivalAt!.Value;At(s,until+2);Join(s,"person:ujiyasu","2");Assert.Equal(new EntityId("org:hojo"),NewGameService.View(s.DiagnosticSnapshot()).House);Assert.Equal(2,s.DiagnosticSnapshot().Service!.Cases.Length);}
    [Fact]public void SaveRestoreAndContinuationAreExact(){var s=Start();var id=Apply(s);var clone=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(s.DiagnosticSnapshot())));foreach(var x in new[]{s,clone}){Send(x,new(new("request:answer"),CareerAction.Accept,id));At(x,4);Open(x);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(clone.DiagnosticSnapshot()));}
    [Theory][InlineData("event")][InlineData("letter")][InlineData("principal")][InlineData("relation")][InlineData("opening")]
    public void ForgedStateIsRejected(string part){var s=Start();Join(s);var w=s.DiagnosticSnapshot();if(part=="event")w.Service=w.Service! with{Events=w.Service.Events.Select(e=>e.Kind==CareerEventKind.Joined?e with{At=0}:e).ToArray()};if(part=="letter")w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Kind=="service-notice"?m with{Body="forged"}:m).ToArray();if(part=="principal")w.Service=w.Service! with{Cases=w.Service.Cases.Select(c=>c with{Principal=new("person:nobunaga")}).ToArray()};if(part=="relation")w.Memberships=w.Memberships.Where(r=>r.Subject!=s.PlayerControl).ToArray();if(part=="opening")w.Service=w.Service! with{Openings=w.Service.Openings.Select(o=>o with{At=0}).ToArray()};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact]public void OldStartsKeepOptionalServiceAbsent(){var w=CareerMilitary.Create();Assert.Null(w.Service);Assert.DoesNotContain("\"Service\"",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));ContractValidation.Validate(w);}
    [Fact]public void PhysicalInquiryCanRecoverUnopenedAgreement(){var s=Start();var id=Apply(s);Send(s,new(new("request:accept"),CareerAction.Accept,id));At(s,4);Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).House);Send(s,new(new("request:inquire"),CareerAction.Inquire,id));At(s,6);var reply=s.DiagnosticSnapshot().Service!.Events.Single(e=>e.Kind==CareerEventKind.StatusSent);s.Open(s.PlayerControl,new(reply.Message),s.Revision);Assert.Equal(new EntityId("org:takeda"),NewGameService.View(s.DiagnosticSnapshot()).House);}
    [Fact]public void LateOpeningOfOriginalAgreementCannotUndoKnownRelease(){var s=Start();var id=Apply(s);Send(s,new(new("request:accept"),CareerAction.Accept,id));At(s,4);Send(s,new(new("request:inquire1"),CareerAction.Inquire,id));At(s,6);var quote=s.DiagnosticSnapshot().Service!.Events.Single(e=>e.Kind==CareerEventKind.StatusSent);s.Open(s.PlayerControl,new(quote.Message),s.Revision);Send(s,new(new("request:leave"),CareerAction.RequestRelease,id));At(s,8);Send(s,new(new("request:inquire2"),CareerAction.Inquire,id));At(s,10);var endQuote=s.DiagnosticSnapshot().Service!.Events.Last(e=>e.Kind==CareerEventKind.StatusSent);s.Open(s.PlayerControl,new(endQuote.Message),s.Revision);var old=s.DiagnosticSnapshot().Service!.Events.Single(e=>e.Kind==CareerEventKind.Joined);s.Open(s.PlayerControl,new(old.Message),s.Revision);Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).House);}

    [Fact]public void CreatedDaimyoCanBeThePrincipal(){var head=NewGameWorldTests.Officer("created:head",StartTemplate.Daimyo,"site:kofu");var player=NewGameWorldTests.Officer(site:"site:kofu");var setup=NewGameWorldTests.Setup([head,player],[new(head.Id,"org:created-head",["site:kofu"],false)]);var session=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,player.Id));Join(session,head.Id);Assert.Equal(new EntityId(head.Id),NewGameService.View(session.DiagnosticSnapshot()).Principal);}

}
